def decode_a1z26(code):
    final_str = ""
    i = 0
    while i < len(code):
        if code[i].isdigit():
            num_str = ""
            while i < len(code) and code[i].isdigit():
                num_str += code[i]
                i += 1
            final_str += chr(int(num_str) + 64)
        else:
            if code[i] != '-':
                final_str += code[i]
            i += 1
    return final_str
