    R = len(grid)
    C = len(grid[0])
    dp = [[0]*C for _ in range(R)]
    dp[0][0] = grid[0][0]
    for i in range(1, R):
        dp[i][0] = dp[i-1][0] + grid[i][0]
    for j in range(1, C):
        dp[0][j] = dp[0][j-1] + grid[0][j]
    for i in range(1, R):
