def forbidden_passage(monsters_list):
    start = (1, 1)
    end = (8, 8)
    monsters = set(monsters_list)
    queue = [[start]]
    visited = {start}
    shortest_path = None
    safe_paths_count = 0

    # BFS
    while queue:
        path = queue.pop(0)
        x, y = path[-1]
        if (x, y) == end:
            shortest_path = path
            break
        moves = [(x+1, y), (x, y+1)]
        for nx, ny in moves:
            if nx <= 8 and ny <= 8 and (nx, ny) not in monsters and (nx, ny) not in visited:
                visited.add((nx, ny))
                new_path = list(path)
                new_path.append((nx, ny))
                queue.append(new_path)

    # DP Counting
    if shortest_path:
        dp = [[0]*9 for _ in range(9)]
        if (1,1) not in monsters:
            dp[1][1] = 1
            for i in range(1, 9):
