                    if (i, j) in monsters:
                        dp[i][j] = 0
                    else:
                        dp[i][j] = dp[i-1][j] + dp[i][j-1]
        safe_paths_count = dp[8][8]
        return True, shortest_path, safe_paths_count
    else:
        return "No safe path"
